// The grid remains scrollable when space is limited, but uses any free sidebar height
// to reveal rows before a scrollbar is needed.
const fitPartsGridToSidebar=()=>{
  if(document.body.classList.contains('partsModalOpen'))return;
  const sidebar=document.querySelector('#sidebarRoot'),panel=document.querySelector('#partsPanel'),grid=document.querySelector('#partsGrid'),settings=document.querySelector('#settingsPanel');
  if(!sidebar||!panel||!grid||panel.classList.contains('sectionCollapsed'))return;
  const sidebarBox=sidebar.getBoundingClientRect(),gridBox=grid.getBoundingClientRect();
  const settingsHeight=settings?.getBoundingClientRect().height||0;
  const rows=partsGridApi?.getDisplayedRowCount?.()??0;
  const headerHeight=partsGridApi?.getHeaderHeight?.()||34;
  const rowHeight=partsGridApi?.getSizesForCurrentTheme?.().rowHeight||32;
  const desiredHeight=Math.max(220,Math.min(680,headerHeight+rows*rowHeight+2));
  const availableHeight=Math.floor(sidebarBox.bottom-gridBox.top-settingsHeight-16);
  const height=availableHeight>300?Math.min(desiredHeight,availableHeight):300;
  grid.style.setProperty('height',`${height}px`,'important');
  partsGridApi?.onGridSizeChanged?.();
};
const sidebarForParts=document.querySelector('#sidebarRoot'),settingsForParts=document.querySelector('#settingsPanel');
if(sidebarForParts){
  if(typeof ResizeObserver!=='undefined'){
    const partsResizeObserver=new ResizeObserver(fitPartsGridToSidebar);
    partsResizeObserver.observe(sidebarForParts);
    if(settingsForParts)partsResizeObserver.observe(settingsForParts);
  }
  new MutationObserver(()=>requestAnimationFrame(fitPartsGridToSidebar)).observe(sidebarForParts,{attributes:true,subtree:true,attributeFilter:['class']});
  window.addEventListener('resize',fitPartsGridToSidebar);
  setTimeout(fitPartsGridToSidebar,350);
}

